SELECT COUNT(*) FROM FIN_BUDGET
 WHERE KIND = #{kind} AND FISCAL_YEAR = #{year} AND CODE = #{code} AND DELETED_YN = 'N'
   AND DETAIL_ID = #{detailId}
   AND DETAIL_ID IS NULL
   AND BUDGET_ID <> #{exceptId}

SELECT  
 WHERE B.KIND = #{kind} AND B.FISCAL_YEAR = #{year} AND B.DELETED_YN = 'N'
   AND B.DEPT_NAME = #{dept}
   AND B.STATUS = #{status}
 ORDER BY PL.FUNC_CODE, PL.PROG_ID, U.PROG_ID, D.PROG_ID, B.CODE

mapper.update:
UPDATE FIN_BUDGET
   SET STATUS = #{toStatus}
       , REQUESTED_AT = #{at}, REVIEW_NOTE = NULL

           , REVIEWER_ID = #{reviewerId}, REVIEWER_NAME = #{reviewerName}, REVIEWED_AT = #{at}, REVIEW_NOTE = #{note}

 WHERE BUDGET_ID = #{budgetId} AND STATUS = #{fromStatus} AND DELETED_YN = 'N'

