SELECT * FROM (
    SELECT  FROM FIN_TXN T
     WHERE T.KIND = #{kind} AND T.FISCAL_YEAR = #{year}
     ORDER BY T.TXN_DATE DESC, T.TXN_ID DESC
) WHERE ROWNUM <= #{limit}

SELECT NVL(SUM(PAY_AMOUNT), 0) FROM APPROVAL_DOC
 WHERE BUDGET_ID = #{budgetId} AND STATUS = 'PROG' AND DELETED_YN = 'N' AND COMMIT_DOC_ID IS NULL
   AND DOC_ID <> #{exceptDocId}

SELECT NVL(SUM(PAY_AMOUNT), 0) FROM APPROVAL_DOC
 WHERE COMMIT_DOC_ID = #{commitDocId} AND STATUS = 'PROG' AND DELETED_YN = 'N'
   AND DOC_ID <> #{exceptDocId}
